   135	static inline void
   136	_remove_invalid_gids (hb_set_t *glyphs,
   137	                      unsigned int num_glyphs)
   138	{
   139	  hb_codepoint_t gid = HB_SET_VALUE_INVALID;
   140	  while (glyphs->next (&gid))
   141	  {
   142	    if (gid >= num_glyphs)
   143	      glyphs->del (gid);
