   147	static void
   148	_populate_gids_to_retain (hb_subset_plan_t* plan,
   149	                          const hb_set_t *unicodes,
   150	                          const hb_set_t *input_glyphs_to_retain,
   151	                          bool close_over_gsub,
   152	                          bool close_over_gpos)
   153	{
   154	  OT::cmap::accelerator_t cmap;
   155	  OT::glyf::accelerator_t glyf;
   156	#ifndef HB_NO_SUBSET_CFF
   157	  OT::cff1::accelerator_t cff;
   158	#endif
   159	  cmap.init (plan->source);
   160	  glyf.init (plan->source);
   161	#ifndef HB_NO_SUBSET_CFF
   162	  cff.init (plan->source);
   163	#endif
   164	
   165	  plan->_glyphset_gsub->add (0); // Not-def
   166	  hb_set_union (plan->_glyphset_gsub, input_glyphs_to_retain);
   167	
   168	  hb_codepoint_t cp = HB_SET_VALUE_INVALID;
   169	  while (unicodes->next (&cp))
   170	  {
   171	    hb_codepoint_t gid;
   172	    if (!cmap.get_nominal_glyph (cp, &gid))
   173	    {
   174	      DEBUG_MSG(SUBSET, nullptr, "Drop U+%04X; no gid", cp);
   175	      continue;
   176	    }
   177	    plan->unicodes->add (cp);
   178	    plan->codepoint_to_glyph->set (cp, gid);
   179	    plan->_glyphset_gsub->add (gid);
   180	  }
   181	
   182	  _cmap_closure (plan->source, plan->unicodes, plan->_glyphset_gsub);
   183	
   184	#ifndef HB_NO_SUBSET_LAYOUT
   185	  if (close_over_gsub)
   186	    // closure all glyphs/lookups/features needed for GSUB substitutions.
   187	    _gsub_closure_glyphs_lookups_features (plan->source, plan->_glyphset_gsub, plan->gsub_lookups, plan->gsub_features);
   188	
   189	  if (close_over_gpos)
   190	    _gpos_closure_lookups_features (plan->source, plan->_glyphset_gsub, plan->gpos_lookups, plan->gpos_features);
   191	#endif
   192	  _remove_invalid_gids (plan->_glyphset_gsub, plan->source->get_num_glyphs ());
   193	
   194	  // Populate a full set of glyphs to retain by adding all referenced
   195	  // composite glyphs.
   196	  hb_codepoint_t gid = HB_SET_VALUE_INVALID;
   197	  while (plan->_glyphset_gsub->next (&gid))
   198	  {
   199	    glyf.add_gid_and_children (gid, plan->_glyphset);
   200	#ifndef HB_NO_SUBSET_CFF
   201	    if (cff.is_valid ())
   202	      _add_cff_seac_components (cff, gid, plan->_glyphset);
   203	#endif
   204	  }
   205	
   206	  _remove_invalid_gids (plan->_glyphset, plan->source->get_num_glyphs ());
   207	
   208	#ifndef HB_NO_SUBSET_CFF
   209	  cff.fini ();
   210	#endif
   211	  glyf.fini ();
   212	  cmap.fini ();
   213	}
