   215	static void
   216	_create_old_gid_to_new_gid_map (const hb_face_t *face,
   217	                                bool             retain_gids,
   218	                                const hb_set_t  *all_gids_to_retain,
   219	                                hb_map_t        *glyph_map, /* OUT */
   220	                                hb_map_t        *reverse_glyph_map, /* OUT */
   221	                                unsigned int    *num_glyphs /* OUT */)
   222	{
   223	  if (!retain_gids)
   224	  {
   225	    + hb_enumerate (hb_iter (all_gids_to_retain), (hb_codepoint_t) 0)
   226	    | hb_sink (reverse_glyph_map)
   227	    ;
   228	    *num_glyphs = reverse_glyph_map->get_population ();
   229	  } else {
   230	    + hb_iter (all_gids_to_retain)
   231	    | hb_map ([] (hb_codepoint_t _) {
   232	                return hb_pair_t<hb_codepoint_t, hb_codepoint_t> (_, _);
   233	              })
   234	    | hb_sink (reverse_glyph_map)
   235	    ;
   236	
   237	    unsigned max_glyph =
   238	    + hb_iter (all_gids_to_retain)
   239	    | hb_reduce (hb_max, 0u)
   240	    ;
   241	    *num_glyphs = max_glyph + 1;
   242	  }
   243	
   244	  + reverse_glyph_map->iter ()
   245	  | hb_map (&hb_pair_t<hb_codepoint_t, hb_codepoint_t>::reverse)
   246	  | hb_sink (glyph_map)
   247	  ;
   248	}
